using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
namespace RaceDay.Api;
public class User { public int UserId {get;set;} [MaxLength(50)] public string FirstName {get;set;}=""; [MaxLength(50)] public string LastName {get;set;}=""; [MaxLength(255)] public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; [MaxLength(30)] public string? Phone {get;set;} public string Role {get;set;}="Participant"; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class RaceEvent { public int EventId {get;set;} public int OrganiserId {get;set;} public User Organiser {get;set;}=null!; [MaxLength(150)] public string Name {get;set;}=""; public DateTime EventDate {get;set;} public string Location {get;set;}=""; public decimal DistanceKm {get;set;} public string? Description {get;set;} public string Status {get;set;}="Upcoming"; public string EventType {get;set;}="Run"; }
public class Category { public int CategoryId {get;set;} public int EventId {get;set;} public RaceEvent Event {get;set;}=null!; public string Name {get;set;}=""; public int MaxParticipants {get;set;} public decimal EntryFee {get;set;} }
public class Enrolment { public int EnrolmentId {get;set;} public int UserId {get;set;} public User User {get;set;}=null!; public int CategoryId {get;set;} public Category Category {get;set;}=null!; public string Status {get;set;}="Registered"; public int? RaceNumber {get;set;} public DateTime EnrolledAt {get;set;}=DateTime.UtcNow; }
public class RaceResult { public int ResultId {get;set;} public int EnrolmentId {get;set;} public Enrolment Enrolment {get;set;}=null!; public TimeSpan FinishTime {get;set;} public int Position {get;set;} public decimal PaceMinPerKm {get;set;} public string ResultStatus {get;set;}="Finished"; }
public class RaceRoute { public int RouteId {get;set;} public int EventId {get;set;} public RaceEvent Event {get;set;}=null!; public string StartPoint {get;set;}=""; public string FinishPoint {get;set;}=""; public string? RouteUrl {get;set;} public decimal? ElevationGainM {get;set;} public string? Notes {get;set;} }
public class RaceDayContext(DbContextOptions<RaceDayContext> options):DbContext(options) {
 public DbSet<User> Users=>Set<User>(); public DbSet<RaceEvent> Events=>Set<RaceEvent>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Enrolment> Enrolments=>Set<Enrolment>(); public DbSet<RaceResult> Results=>Set<RaceResult>(); public DbSet<RaceRoute> Routes=>Set<RaceRoute>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<User>().HasKey(x=>x.UserId); b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<User>().Property(x=>x.Role).HasMaxLength(20); b.Entity<User>().Property(x=>x.PasswordHash).HasMaxLength(255);
  b.Entity<RaceEvent>().HasKey(x=>x.EventId); b.Entity<RaceEvent>().HasOne(x=>x.Organiser).WithMany().HasForeignKey(x=>x.OrganiserId).OnDelete(DeleteBehavior.Restrict); b.Entity<RaceEvent>().Property(x=>x.DistanceKm).HasPrecision(8,2); b.Entity<RaceEvent>().Property(x=>x.EventDate).HasColumnType("date"); b.Entity<RaceEvent>().Property(x=>x.Location).HasMaxLength(150); b.Entity<RaceEvent>().Property(x=>x.Description).HasMaxLength(1000); b.Entity<RaceEvent>().Property(x=>x.Status).HasMaxLength(20); b.Entity<RaceEvent>().Property(x=>x.EventType).HasMaxLength(10);
  b.Entity<Category>().HasKey(x=>x.CategoryId); b.Entity<Category>().HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict); b.Entity<Category>().HasIndex(x=>new{x.EventId,x.Name}).IsUnique(); b.Entity<Category>().Property(x=>x.Name).HasMaxLength(100); b.Entity<Category>().Property(x=>x.EntryFee).HasPrecision(10,2);
  b.Entity<Enrolment>().HasKey(x=>x.EnrolmentId); b.Entity<Enrolment>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict); b.Entity<Enrolment>().HasOne(x=>x.Category).WithMany().HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict); b.Entity<Enrolment>().HasIndex(x=>new{x.UserId,x.CategoryId}).IsUnique(); b.Entity<Enrolment>().HasIndex(x=>x.RaceNumber).IsUnique().HasFilter("[RaceNumber] IS NOT NULL"); b.Entity<Enrolment>().Property(x=>x.Status).HasMaxLength(20);
  b.Entity<RaceResult>().HasKey(x=>x.ResultId); b.Entity<RaceResult>().HasOne(x=>x.Enrolment).WithMany().HasForeignKey(x=>x.EnrolmentId).OnDelete(DeleteBehavior.Restrict); b.Entity<RaceResult>().HasIndex(x=>x.EnrolmentId).IsUnique(); b.Entity<RaceResult>().Property(x=>x.FinishTime).HasColumnType("time(0)"); b.Entity<RaceResult>().Property(x=>x.PaceMinPerKm).HasPrecision(8,2); b.Entity<RaceResult>().Property(x=>x.ResultStatus).HasMaxLength(20);
  b.Entity<RaceRoute>().HasKey(x=>x.RouteId); b.Entity<RaceRoute>().HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict); b.Entity<RaceRoute>().HasIndex(x=>x.EventId).IsUnique(); b.Entity<RaceRoute>().Property(x=>x.StartPoint).HasMaxLength(255); b.Entity<RaceRoute>().Property(x=>x.FinishPoint).HasMaxLength(255); b.Entity<RaceRoute>().Property(x=>x.RouteUrl).HasMaxLength(500); b.Entity<RaceRoute>().Property(x=>x.Notes).HasMaxLength(1000); b.Entity<RaceRoute>().Property(x=>x.ElevationGainM).HasPrecision(10,2);
 }
}
